MARKERY_STAROGO = ("ГДЕ МАШИНА СЕЙЧАС", "УСЛОВИЯ", "Проверить VIN",
                   "Предоплата:", "Срок прибытия после оплаты:")


def vklyuchit_zamenu():
    """Старые текстовые простыни клиентского бота заменяем на короткое
    сообщение с кнопкой на дизайн-страницу."""
    try:
        from telegram.ext import ExtBot
        from telegram import InlineKeyboardMarkup, InlineKeyboardButton, WebAppInfo
    except Exception:
        return False
    if getattr(ExtBot, "_zamena_vitriny", False):
        return True

    klientskij = fajl("bot_token.txt")
    staryj = ExtBot.send_message

    async def novyj(self, *args, **kw):
        try:
            if klientskij and getattr(self, "token", "") == klientskij:
                tekst = kw.get("text") or ""
                if not tekst:
                    for a in args:
                        if isinstance(a, str) and len(a) > 30:
                            tekst = a
                            break
                if tekst and sum(1 for m in MARKERY_STAROGO if m in tekst) >= 2:
                    najdeno = re.search(r"\bUA-\d{3,5}\b", tekst)
                    nuzhna = None
                    if najdeno:
                        for m in mashiny():
                            if nomer(m) == najdeno.group(0):
                                nuzhna = m
                                break
                    if nuzhna is not None:
                        nom = nomer(nuzhna)
                        korotkij, _ = tekst_mashiny(nuzhna)
                        ryady = [[InlineKeyboardButton(
                            "🚗  Открыть карточку",
                            web_app=WebAppInfo(url="%s/%s.html" % (sajt(), nom)))]]
                        if stranica_est(nuzhna):
                            ryady.append([InlineKeyboardButton(
                                "Все машины", callback_data="v_cars")])
                        kw["text"] = korotkij
                        kw["parse_mode"] = "HTML"
                        kw["reply_markup"] = InlineKeyboardMarkup(ryady)
                        chat = kw.get("chat_id")
                        if chat is None and args:
                            chat = args[0]
                        zapis("%s: старый экран заменён коротким" % nom)
                        return await staryj(self, chat_id=chat, **{
                            k: v for k, v in kw.items() if k != "chat_id"})
        except Exception as e:
            zapis("замена экрана: %s" % e)
        return await staryj(self, *args, **kw)

    ExtBot.send_message = novyj
    ExtBot._zamena_vitriny = True
    zapis("замена старых экранов включена")
    return True


def vklyuchit():
    try:
        from telegram.ext import Application
    except Exception:
        return False
    vklyuchit_zamenu()
    if getattr(Application, "_vitrina", False):
        return True

    klientskij = fajl("bot_token.txt")
    staryj = Application.process_update

    async def novyj(self, update):
        try:
            if klientskij and getattr(self.bot, "token", "") == klientskij:
                if await obrabotat(self, update):
                    return
        except Exception as e:
            zapis("разбор: %s" % e)
        return await staryj(self, update)

    Application.process_update = novyj
    Application._vitrina = True
    zapis("витрина по макету включена")
    return True


def postavit_menu():
    """Синюю кнопку «Меню» у поля ввода заменяем на «Каталог» — вход в один тап."""
    try:
        tok = fajl("bot_token.txt")
        if not tok:
            return
        telo = json.dumps({
            "menu_button": {
                "type": "web_app",
                "text": "UA ART",
                "web_app": {"url": "%s/index.html" % sajt()},
            }
        }).encode("utf-8")
        zapros = urllib.request.Request(
            "[URL]" % tok,
            data=telo, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(zapros, timeout=15) as otvet:
            otvet.read()
        zapis("кнопка меню переведена на каталог")
    except Exception as e:
        zapis("кнопка меню: %s" % e)


def start():
    threading.Thread(target=postavit_menu, daemon=True).start()
    if vklyuchit():
        return

    def zhdat():
        for _ in range(120):
            time.sleep(5)
            if vklyuchit():
                return
    threading.Thread(target=zhdat, daemon=True).start()


def podklyuchit():
    itog = []
    stroka = "try:\n    import vitrina; vitrina.start()\nexcept Exception:\n    pass\n"
    for ver in ("3.10", "3.13"):
        papka = os.path.expanduser("~/.local/lib/python%s/site-packages" % ver)
        if not os.path.isdir(papka):
            itog.append("python %s — нет" % ver)
            continue
        uc = os.path.join(papka, "usercustomize.py")
        t = chitat(uc) if os.path.exists(uc) else ""
        if "import vitrina" not in t:
            t = t.rstrip() + "\n\n" + stroka
        try:
            compile(t, uc, "exec")
        except SyntaxError as e:
            itog.append("python %s — отменено, синтаксис (строка %s)" % (ver, e.lineno))
            continue
        try:
            with io.open(uc + ".proshlyy", "w", encoding="utf-8") as f:
                f.write(chitat(uc) if os.path.exists(uc) else "")
        except Exception:
            pass
        with io.open(uc, "w", encoding="utf-8") as f:
            f.write(t)
        itog.append("python %s — подключено" % ver)
    return itog


def main():
    print("ВИТРИНА ПО УТВЕРЖДЁННОМУ МАКЕТУ — %s" % time.strftime("%d.%m.%Y %H:%M"))
    print()
    for s in podklyuchit():
        print(" ", s)
    print()
    spisok_mashin = mashiny()
    print("машин на витрине: %d" % len(spisok_mashin))
    for m in spisok_mashin:
        etap_tekst, bron = etap(m)
        print("  %s · %s · %s · %s · карточка %s · бронь %s"
              % (nomer(m), zagolovok(m), cena(m), etap_tekst,
                 "есть" if stranica_est(m) else "НЕТ",
                 "да" if bron else "нет"))
    print()
    print("владелец для заявок: %s" % (fajl("vladelec.txt") or "НЕ ЗАДАН — заявки не придут"))
    print("адрес карточек: %s" % sajt())
    print()
    print("дальше: Tasks → Restart, затем /start в клиентском боте")


if __name__ == "__main__":
    main()

